import {SAMPLE_TIMES,dateKey,toUTC,formatDate,validDetails,calendarDraft} from './scheduling-core.mjs';
const q=s=>document.querySelector(s),names={zoom:'Zoom',teams:'Microsoft Teams',whatsapp:'WhatsApp call'},topics={website:'Developing your business website',redesign:'Improving your existing website',digital:'Planning your digital transformation'};
let detected='Asia/Colombo';try{detected=Intl.DateTimeFormat().resolvedOptions().timeZone}catch{}
if(!Array.from(q('#schedule-zone').options).some(o=>o.value===detected)){const o=document.createElement('option');o.value=detected;o.textContent=detected.replaceAll('_',' ');q('#schedule-zone').appendChild(o)}q('#schedule-zone').value=detected;
const currentMonth=()=>dateKey(new Date(),state.zone).slice(0,7);
const state={platform:'zoom',zone:detected,date:'',time:'',month:'',stage:0};state.month=currentMonth();
const pages=['#schedule-time','#schedule-details','#schedule-review','#schedule-complete'];
function setStage(stage){state.stage=stage;pages.forEach((id,i)=>{q(id).hidden=i!==stage});document.querySelectorAll('[data-stage-indicator]').forEach((el,i)=>{el.classList.toggle('completed',stage>i);if(i===stage)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});q('.schedule-progress').hidden=stage===3;q('#scheduler').scrollTop=0;const heading=q(pages[stage]).querySelector('h3');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}
function focusTopic(){return topics[q('#priority').value]||topics.website}
function refreshTopic(){q('#meeting-topic-text').textContent=focusTopic();q('#schedule-focus').textContent=focusTopic()}
function setPlatform(platform){if(!names[platform])return;state.platform=platform;document.querySelectorAll('[data-platform],[data-schedule-platform]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.platform||b.dataset.schedulePlatform)===platform)));q('#whatsapp-fields').hidden=platform!=='whatsapp';q('#schedule-phone').required=platform==='whatsapp';q('#details-error').textContent='';q('#schedule-phone').setCustomValidity('');q('#meeting-booking').replaceChildren();const h=document.createElement('h3');h.textContent=names[platform];const p=document.createElement('p');p.textContent=platform==='whatsapp'?'A scheduled voice or video call using your WhatsApp number.':'A focused video conversation about your next business improvement.';q('#meeting-booking').append(h,p);if(state.stage===3)setStage(0);if(state.stage===2)renderReview()}
function openScheduler(){refreshTopic();q('#scheduler').showModal();if(state.stage===3)setStage(0);renderCalendar();renderTimes();updateSelection();if(!q('#schedule-company').value)q('#schedule-company').value=q('#business-name').value;setStage(state.stage)}
function updateSelection(){q('#schedule-selection').textContent=state.date?formatDate(state.date)+(state.time?' · '+state.time:'')+' · '+state.zone.replaceAll('_',' '):'Choose your date and time'}
function renderCalendar(){const [year,month]=state.month.split('-').map(Number);q('#calendar-month').textContent=new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(year,month-1,1)));const grid=q('#calendar-days');grid.replaceChildren();const start=(new Date(Date.UTC(year,month-1,1)).getUTCDay()+6)%7,total=new Date(Date.UTC(year,month,0)).getUTCDate(),today=dateKey(new Date(),state.zone);for(let i=0;i<start;i++){const blank=document.createElement('span');blank.setAttribute('aria-hidden','true');grid.appendChild(blank)}for(let d=1;d<=total;d++){const key=state.month+'-'+String(d).padStart(2,'0'),button=document.createElement('button');button.type='button';button.textContent=String(d);button.disabled=key<today;button.setAttribute('aria-label',formatDate(key));button.setAttribute('aria-pressed',String(state.date===key));if(key===today)button.classList.add('today');button.addEventListener('click',()=>{state.date=key;state.time='';q('#time-error').textContent='';renderCalendar();renderTimes();updateSelection()});grid.appendChild(button)}q('#previous-month').disabled=state.month<=currentMonth();const maxMonth=new Date(Date.UTC(Number(today.slice(0,4)),Number(today.slice(5,7))-1+3,1)).toISOString().slice(0,7);q('#next-month').disabled=state.month>=maxMonth}
function renderTimes(){const box=q('#time-slots');box.replaceChildren();q('#time-date').textContent=state.date?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(state.date+'T12:00:00Z')):'Select a date';if(!state.date){const p=document.createElement('p');p.className='time-placeholder';p.textContent='Choose a day to explore example meeting times.';box.appendChild(p);return}const times=SAMPLE_TIMES.filter(t=>{try{return toUTC(state.date,t,state.zone)>new Date()}catch{return false}});if(!times.length){const p=document.createElement('p');p.className='time-placeholder';p.textContent='There are no future example times on this day. Choose another date.';box.appendChild(p);return}for(const t of times){const b=document.createElement('button');b.type='button';b.textContent=t;b.setAttribute('aria-pressed',String(state.time===t));b.setAttribute('aria-label',t+' on '+formatDate(state.date)+' in '+state.zone);b.addEventListener('click',()=>{state.time=t;q('#time-error').textContent='';renderTimes();updateSelection()});box.appendChild(b)}}
function checkTime(){if(!state.date||!state.time){q('#time-error').textContent='Choose a date and an example time to continue.';return false}try{if(toUTC(state.date,state.time,state.zone)<=new Date())throw Error();return true}catch{q('#time-error').textContent='That time has passed or is unavailable. Choose another time.';state.time='';renderTimes();return false}}
function getDetails(){return {name:q('#schedule-name').value.trim(),email:q('#schedule-email').value.trim(),company:q('#schedule-company').value.trim(),phone:q('#schedule-phone').value.trim(),goal:q('#schedule-goal').value.trim()}}
function callName(){return state.platform==='whatsapp'?'WhatsApp '+(q('#schedule-call-type').value==='video'?'video':'voice')+' call':names[state.platform]}
function addReview(dl,label,value){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);dl.appendChild(row)}
function renderReview(){const d=getDetails(),list=q('#review-list');list.replaceChildren();addReview(list,'Meeting',callName());addReview(list,'When',formatDate(state.date)+' · '+state.time);addReview(list,'Timezone',state.zone.replaceAll('_',' '));addReview(list,'Duration','30 minutes');addReview(list,'Name',d.name);addReview(list,'Email',d.email);if(d.company)addReview(list,'Business',d.company);if(state.platform==='whatsapp')addReview(list,'WhatsApp call number',d.phone);addReview(list,'Focus',focusTopic());if(d.goal)addReview(list,'Your priority',d.goal)}
document.querySelectorAll('[data-platform]').forEach(b=>b.addEventListener('click',()=>setPlatform(b.dataset.platform)));document.querySelectorAll('[data-schedule-platform]').forEach(b=>b.addEventListener('click',()=>setPlatform(b.dataset.schedulePlatform)));document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',refreshTopic));q('#priority').addEventListener('change',refreshTopic);q('#visitor-timezone').textContent='Your timezone: '+detected.replaceAll('_',' ');q('#begin-scheduling').addEventListener('click',openScheduler);
q('#schedule-zone').addEventListener('change',()=>{state.zone=q('#schedule-zone').value;state.time='';const today=dateKey(new Date(),state.zone);if(state.date&&state.date<today)state.date='';if(state.month<today.slice(0,7))state.month=today.slice(0,7);renderCalendar();renderTimes();updateSelection()});for(const [id,delta] of [['#previous-month',-1],['#next-month',1]])q(id).addEventListener('click',()=>{const [y,m]=state.month.split('-').map(Number);state.month=new Date(Date.UTC(y,m-1+delta,1)).toISOString().slice(0,7);renderCalendar()});q('#time-next').addEventListener('click',()=>{if(checkTime())setStage(1)});q('#details-back').addEventListener('click',()=>setStage(0));q('#schedule-phone').addEventListener('input',()=>q('#schedule-phone').setCustomValidity(''));
q('#schedule-details').addEventListener('submit',event=>{event.preventDefault();const errors=validDetails(getDetails(),state.platform),first=Object.keys(errors)[0];if(first){q('#details-error').textContent=errors[first];q('#schedule-'+first).focus();return}q('#details-error').textContent='';if(!checkTime()){setStage(0);return}renderReview();setStage(2)});q('#review-back').addEventListener('click',()=>setStage(1));q('#finish-preview').addEventListener('click',()=>{if(!checkTime()){setStage(0);return}const errors=validDetails(getDetails(),state.platform);if(Object.keys(errors).length){q('#details-error').textContent=Object.values(errors)[0];setStage(1);return}const box=q('#complete-summary');box.replaceChildren();const title=document.createElement('strong');title.textContent=callName();const date=document.createElement('p');date.textContent=formatDate(state.date)+' · '+state.time+' · '+state.zone.replaceAll('_',' ');const focus=document.createElement('p');focus.textContent=focusTopic();box.append(title,date,focus);q('#calendar-status').textContent='';setStage(3)});q('#edit-preview').addEventListener('click',()=>setStage(0));q('#close-preview').addEventListener('click',()=>q('#scheduler').close());q('#save-calendar-draft').addEventListener('click',()=>{const data=calendarDraft({date:state.date,time:state.time,zone:state.zone,platform:state.platform,callType:q('#schedule-call-type').value,focus:focusTopic(),uid:crypto.randomUUID()+'@preview.workxit'});const url=URL.createObjectURL(new Blob([data],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='WORKX-IT-Meeting-Preview.ics';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);q('#calendar-status').textContent='Draft saved with “PREVIEW — NOT BOOKED” in its title. No invitations were sent.'});setPlatform('zoom');refreshTopic();renderCalendar();renderTimes();
